    "layer": 1,
    "guardian_lock": true,
    "change_requires": "gardener_approval",
    "created": "2026-02-23",
    "version_history": [
      {
        "version": "v1.0.0",
        "date": "2026-02-23",
        "summary": "Создание модуля."
      },
